INSERT INTO `clubs` VALUES (1,'CSSEC','Computer Science Student Exec Council','Academic','CS & IT','Official executive council of Computer Science and IT students, fostering technical skills, collaborative software engineering, open-source innovation, and industry competitive programming.',17,'Prof. Alex Reyes','Active','BSCS','2026-10-06 01:48:06',NULL),(2,'ACADS','Association of Computer Eng Driven Students','Academic','Computer Engineering','Association dedicated to academic rigor and engineering excellence through peer tutorials, embedded system research, circuit design workshops, and regional technical competitions.',18,'Prof. Mark Velo','Active','BSCpE','2026-10-06 01:48:06',NULL),(3,'ACES','Association of Computer Engineering Students','Academic','Computer Engineering','Professional student chapter promoting hardware innovation, robotics, networking infrastructure, and industry certifications for computer engineering students.',19,'Prof. Elena Ramos','Active','BSCpE','2026-10-06 01:48:06',NULL),(4,'AISS','Accounting Info System Society','Academic','Accounting & Finance','Advances accounting information literacy, enterprise resource planning, and financial technology integration across academic and commercial business applications.',20,'Prof. Clara Tan','Active','BSAIS','2026-10-06 01:48:06',NULL),(5,'BLISS','Bestlink Library & Info Science Society','Academic','Library & Information Science','Fosters modern digital library science, information curation, scholarly database research, and knowledge preservation across BCP faculties.',21,'Prof. Robert Cruz','Active','BLIS','2026-10-06 01:48:06',NULL),(6,'BRAVE','Values Education & Accountability Org','Academic','Education & Values','Champions ethics, character formation, civic responsibility, and values-centered pedagogy among future educators and campus leaders.',22,'Prof. Diana Gomez','Active','BSEd','2026-10-06 01:48:06',NULL),(7,'CJSU','Criminal Justice Student Unit','Academic','Criminal Justice','Strengthens criminology students through criminalistics workshops, tactical drills, moot court trials, and community law enforcement partnerships.',23,'Prof. Jose Mercado','Active','BSCrim','2026-10-06 01:48:06',NULL),(8,'EYO','Entrepreyouth Organization','Academic','Business & Entrepreneurship','Incubates youth-led commercial startups, sustainable social ventures, and retail product exhibitions with professional mentorship.',24,'Prof. Lisa Santos','Active','BSBA','2026-10-06 01:48:06',NULL),(9,'G.A.L.A.W','Athletes & Leaders Wellness Assoc','Academic','Physical Education & Wellness','Promotes physical literacy, athletic conditioning, sports science education, and holistic campus wellness initiatives.',25,'Prof. Manuel Cruz','Active','Institutional','2026-10-06 01:48:06',NULL),(10,'GEMs','Guild of English Majors','Academic','Language & Humanities','Fosters English linguistic excellence, literary appreciation, forensic speech, parliamentary debate, and creative writing.',26,'Prof. Anna Reyes','Active','BSEd','2026-10-06 01:48:06',NULL),(11,'GOLD','Guild of Officers to Lead Development','Academic','Leadership & Governance','Develops executive leadership, organizational diplomacy, parliamentary procedure, and administrative excellence among campus leaders.',27,'Prof. Karen Lim','Active','Institutional','2026-10-06 01:48:06',NULL),(12,'JFINEX','Junior Financial Executives','Academic','Accounting & Finance','Enhances financial literacy, stock exchange analytics, corporate financial management, and investment principles for business students.',28,'Prof. Manuel Cruz','Active','BSBA','2026-10-06 01:48:06',NULL),(13,'HRS','Human Resources Society','Academic','Management & Administration','Equips office administration and business majors with modern talent management, labor law compliance, and organizational behavior skills.',29,'Prof. Alex Reyes','Active','BSBA','2026-10-06 01:48:06',NULL),(14,'J.M.A','Junior Marketing Association','Academic','Business & Entrepreneurship','Specializes in strategic brand marketing, digital media campaigns, market research, and consumer engagement case studies.',30,'Prof. Sarah Mercado','Active','BSBA','2026-10-06 01:48:06',NULL),(15,'LAKAS','Liga ng Aktibong Kabataan sa Araling Panlipunan','Academic','Education & Values','Promotes civic engagement, Philippine social history, political awareness, and transformative social studies pedagogy.',31,'Prof. Clara Tan','Active','BSEd','2026-10-06 01:48:06',NULL),(16,'L.A.P.I.S','Leadership Assoc Program & Services','Academic','Leadership & Governance','Provides servant leadership training, grassroots outreach missions, disaster relief coordination, and youth volunteerism.',32,'Prof. Diana Gomez','Active','Institutional','2026-10-06 01:48:06',NULL),(17,'LIBRO','Lucid of Bright & Righteous Officers','Academic','Library & Information Science','Champions reading campaigns, archival preservation, community mobile libraries, and digital book accessibility across campuses.',33,'Prof. Robert Cruz','Active','BLIS','2026-10-06 01:48:06',NULL),(18,'OMEGA','Org for Mathematics in Engineering','Academic','Mathematics & Applied Sciences','Applies advanced mathematical modeling, calculus, and computational algorithms to solving complex engineering and scientific problems.',34,'Prof. Jose Mercado','Active','BSCpE','2026-10-06 01:48:06',NULL),(19,'PsychSoc','Psychology Society','Academic','Social Sciences','Advances psychological awareness, mental health advocacy, behavioral research, and peer counseling support across the student community.',35,'Prof. Lisa Santos','Active','BSPsych','2026-10-06 01:48:06',NULL),(20,'RSD','Regnum Scientiae Discipulus','Academic','Mathematics & Applied Sciences','Fosters scientific inquiry, experimental laboratory research, STEM innovation, and peer tutoring in biological and physical sciences.',36,'Prof. Anna Reyes','Active','Institutional','2026-10-06 01:48:06',NULL),(21,'SIGMA','Guild for Mathematics Majors','Academic','Mathematics & Applied Sciences','Explores pure and applied mathematics, statistics, competition mathematics, and quantitative problem-solving strategies.',37,'Prof. Karen Lim','Active','BSEd','2026-10-06 01:48:06',NULL),(22,'TECHs','Tech, Exploratory & Hospitality Skills','Academic','Hospitality & Culinary Arts','Develops culinary arts mastery, hotel operations proficiency, food service safety, and front-of-house hospitality standards.',38,'Prof. Alex Reyes','Active','BSHM','2026-10-06 01:48:06',NULL),(23,'TTS','Tourism Student Society','Academic','Tourism & Travel','Equips tourism management students with airline ticketing, tour packaging, ecotourism development, and cultural heritage skills.',39,'Prof. Sarah Mercado','Active','BSTM','2026-10-06 01:48:06',NULL),(24,'WIKA','Wikang Filipino sa Akademya','Academic','Language & Humanities','Itinataguyod ang pananaliksik, pagpapahalaga, at pagpapaunlad ng wikang Filipino at panitikang pambansa sa antas tersyarya.',40,'Prof. Clara Tan','Active','BSEd','2026-10-06 01:48:06',NULL),(25,'ACAC','Association of Cultural Art Club','Cultural','Department Based Talent Group','Visual and cultural arts collective representing folk arts, painting, theatrical installations, and cultural exhibitions.',41,'Prof. Sarah Mercado','Active','Institutional','2026-10-06 01:48:06',NULL),(26,'CESC','Computer Engineering Sports Club','Sports','Department Based Talent Group','Coordinates sports tournaments, e-sports invitationals, and athletic wellness leagues specifically for engineering students.',42,'Prof. Mark Velo','Active','BSCpE','2026-10-06 01:48:06',NULL),(27,'EBCPCT','Elite BCP Chess Team','Sports','Department Based Talent Group','Elite competitive chess team competing in inter-collegiate board championships, rapid chess tourneys, and strategic clinics.',43,'Prof. Mark Velo','Active','Institutional','2026-10-06 01:48:06',NULL),(28,'RCYC-BCP','Red Cross Youth Council - BCP','Advocacy','Department Based Talent Group','Official Red Cross youth chapter specializing in emergency first aid, blood donation drives, disaster relief, and safety education.',44,'Prof. Elena Cruz','Active','Institutional','2026-10-06 01:48:06',NULL),(29,'SMC','Shuttle Master Club','Sports','Department Based Talent Group','Competitive badminton club providing collegiate training, tactical drills, and inter-university tournament participation.',45,'Prof. Mark Velo','Active','Institutional','2026-10-06 01:48:06',NULL),(30,'ALL STAR','All Star Talent Group','Cultural','Talent Center','BCP premier multi-disciplinary talent troupe specializing in variety stage performances, singing, and modern choreography.',46,'Prof. Sarah Mercado','Active','Institutional','2026-10-06 01:48:06',NULL),(31,'B-FORCE','B-Force Hip-Hop Crew','Cultural','Talent Center','Award-winning campus hip-hop dance crew representing BCP in collegiate streetdance battles, choreography showcases, and concert stages.',47,'Prof. Sarah Mercado','Active','Institutional','2026-10-06 01:48:06',NULL),(32,'CREATIVE','Creative Arts Group','Cultural','Talent Center','Graphic design, digital illustration, and multimedia arts collective crafting visual branding and creative showcases.',48,'Prof. Sarah Mercado','Active','Institutional','2026-10-06 01:48:06',NULL),(33,'CDC','Criminology Dance Company','Cultural','Talent Center','Dynamic performing dance troupe from the College of Criminology blending precision drill steps with modern street dance.',49,'Prof. Sarah Mercado','Active','BSCrim','2026-10-06 01:48:06',NULL),(34,'DLC','Drum and Lyre Corporation','Cultural','Talent Center','BCP official marching drum and lyre corporation providing ceremonial music, parade fanfares, and collegiate rally anthems.',50,'Prof. Sarah Mercado','Active','Institutional','2026-10-06 01:48:06',NULL),(35,'IKATLONG','Ikatlong Lahi Royalties','Cultural','Talent Center','Cultural arts guild dedicated to celebrating Philippine indigenous heritage, traditional folk dances, and cultural storytelling.',51,'Prof. Sarah Mercado','Active','Insti