INSERT INTO `chat_messages` VALUES (1,58,NULL,NULL,1,'Good day respected faculty advisers and SSC council members! This institutional channel is dedicated to multi-tier campus coordination, activity approvals, and semester calendar synchronization.',0,NULL,'2026-10-05 23:48:07'),(2,17,NULL,NULL,1,'Acknowledged, Supreme Student Council! CSSEC and academic faculty advisers are prepared to coordinate upcoming activity schedules.',0,NULL,'2026-10-06 00:48:07'),(3,17,NULL,1,2,'Welcome to the CSSEC General Club Chat! All active members, student officers, and faculty advisers can connect here for announcements and general organization discussions.',0,NULL,'2026-10-05 22:48:07'),(4,1,NULL,1,2,'Good day everyone! Welcome to all new and returning CSSEC members. Our upcoming general orientation details will be posted here soon.',0,NULL,'2026-10-05 23:48:07'),(5,7,NULL,1,2,'Hello Prof. Alex and Officers! Excited for this semester’s CSSEC activities!',0,NULL,'2026-10-06 00:48:07'),(6,17,NULL,1,3,'CSSEC Executive Board: Please finalize the activity proposal and budget breakdown for our upcoming tech symposium prior to submission.',0,NULL,'2026-10-05 23:48:07'),(7,1,NULL,1,3,'Noted Prof. Alex! The student executive committee has reviewed the venue requirements and the requisition is ready for endorsement.',0,NULL,'2026-10-06 01:03:07'),(8,1,NULL,1,2,'Hello po!',0,NULL,'2026-10-06 10:13:06'),(9,118,18,NULL,NULL,'Magandang Buhay!',0,NULL,'2026-10-15 03:35:21');
