INSERT INTO `budget_requests` VALUES (23,1,'Cloud Architecture Hackathon Venue & Server Resources','Server cloud credits, network routers, and lab venue logistics for CSSEC hackathon.','[{\"item\":\"AWS & Cloud Compute Credits\",\"description\":\"Sandbox server instances for 25 competing teams\",\"qty\":25,\"unit_cost\":500,\"total\":12500},{\"item\":\"Gigabit Managed Switches & Patch Cables\",\"description\":\"Local area network setup in Main Auditorium\",\"qty\":5,\"unit_cost\":1500,\"total\":7500},{\"item\":\"Hackathon Medals, Certificates & ID Lanyards\",\"description\":\"Official participant kits and winner plaques\",\"qty\":100,\"unit_cost\":50,\"total\":5000}]',25000.00,25000.00,25000.00,'Disbursed',1,'Official clearance granted by Admin & Disbursed via Accounting Check #0041.','2026-09-15 06:00:00','CHK-2026-0041',59,'2026-10-18 01:57:17','2026-10-18 05:15:27',NULL),(24,28,'Red Cross Blood Drive Medical Supplies & Donor Care Kits','Clinical sterile test kits, post-donation vitamins, recovery refreshments, and cots.','[{\"item\":\"Sterile Blood Typing & Hemoglobin Lancets\",\"description\":\"Pre-screening supplies for 200 student donors\",\"qty\":4,\"unit_cost\":2000,\"total\":8000},{\"item\":\"Donor Recovery Nutrition Packs\",\"description\":\"Iron supplements, juice boxes, and energy biscuits\",\"qty\":200,\"unit_cost\":35,\"total\":7000},{\"item\":\"Medical Triage Tarpaulins & Sanitation Alcohol\",\"description\":\"Disinfectant gallons and directional signage\",\"qty\":7,\"unit_cost\":500,\"total\":3500}]',18500.00,18500.00,18500.00,'Disbursed',1,'Co-funded by Health Services. Official receipt verified.','2026-09-28 03:30:00','CHK-2026-0052',59,'2026-10-18 01:57:17','2026-10-18 05:15:27',NULL),(25,30,'Philippine Cultural Heritage Festival Costumes & Sound Equipment','Traditional Mindanao and Cordillera hand-woven textiles and sound equipment rentals.','[{\"item\":\"Indigenous Folk Dance Costume Ensemble\",\"description\":\"Traditional attire rental & acces