tal\":3000}]',19500.00,18500.00,NULL,'Pending Admin',39,'SSC vetted line items and recommended ₱18,500.00 for Admin release.',NULL,NULL,NULL,'2026-10-18 05:15:27','2026-10-18 05:15:27',NULL),(35,4,'FinTech & Digital Audit Simulation Software Licenses','Cloud ERP student sandbox licenses, forensic accounting casebooks, and seminar certificates.','[{\"item\":\"Enterprise Accounting Sandbox Subscriptions\",\"description\":\"30-day multi-user academic cloud ERP seats\",\"qty\":50,\"unit_cost\":200,\"total\":10000},{\"item\":\"Forensic Audit Case Study Workbooks\",\"description\":\"Printed ledger audit packets for workshop\",\"qty\":120,\"unit_cost\":35,\"total\":4200},{\"item\":\"CPA Guest Lecturer Honorarium & Plaque\",\"description\":\"Resource person token of appreciation\",\"qty\":1,\"unit_cost\":3300,\"total\":3300}]',17500.00,17500.00,NULL,'Pending Admin',20,'Reviewed & forwarded by SSC: Full amount recommended for academic lab simulation.',NULL,NULL,NULL,'2026-10-18 05:15:27','2026-10-18 05:15:27',NULL),(36,8,'Young Entrepreneurs Startup Fair Booth Tents & Electricals','Collapsible bazaar tents, heavy-duty extension cords, and Best Startup Pitch cash awards.','[{\"item\":\"Heavy-Duty 3x3m Collapsible Canopy Tents\",\"description\":\"Outdoor quadrangle stalls for 15 student startups\",\"qty\":15,\"unit_cost\":900,\"total\":13500},{\"item\":\"Industrial Extension Reels & Circuit Breakers\",\"description\":\"Safe power distribution for food & tech stalls\",\"qty\":6,\"unit_cost\":850,\"total\":5100},{\"item\":\"Best Venture Pitch Trophies & Judges Kits\",\"description\":\"Acrylic plaques and scoring portfolios\",\"qty\":1,\"unit_cost\":3400,\"total\":3400}]',22000.00,20500.00,NULL,'Pending Admin',24,'SSC reviewed & endorsed ₱20,500.00 to Administration.',NULL,NULL,NULL,'2026-10-18 05:15:27','2026-10-18 05:15:27',NULL),(37,12,'Collegiate Stock Market & Equity Valuation Trading Terminal','Live market data feed pass, financial calculator units, and corporate summit snacks.','[{\"item\":\"PSE Stock Market Simulator Team Passes\",\"description\":\"Real-time virtual trading platform access for 30 teams\",\"qty\":30,\"unit_cost\":250,\"total\":7500},{\"item\":\"Financial Analyst Summit Delegate Refreshments\",\"description\":\"AM\\/PM snacks for 150 business administration delegates\",\"qty\":150,\"unit_cost\":40,\"total\":6000},{\"item\":\"Certificates, Plaques & Stage Tarpaulin\",\"description\":\"Recognition awards for Top 3 Portfolio Managers\",\"qty\":1,\"unit_cost\":2500,\"total\":2500}]',16000.00,NULL,NULL,'Pending SSC',28,'Endorsed by Club Adviser Prof. Manuel Cruz. Awaiting SSC line-item review.',NULL,NULL,NULL,'2026-10-18 05:15:27','2026-10-18 05:15:27',NULL),(38,10,'Parliamentary Debate & Literary Folio Printing Requisition','Publication of annual student literary anthology, adjudication sheets, and debate timers.','[{\"item\":\"Literary Folio Book Printing (250 copies)\",\"description\":\"80-page perfect-bound student poetry & prose anthology\",\"qty\":250,\"unit_cost\":48,\"total\":12000},{\"item\":\"Debate Championship Trophies & Gavels\",\"description\":\"Best Speaker & Champion Team awards\",\"qty\":4,\"unit_cost\":650,\"total\":2600},{\"item\":\"Adjudication Scorecards & Timekeeper Bells\",\"description\":\"Official British Parliamentary scoring packets\",\"qty\":1,\"unit_cost\":1200,\"total\":1200}]',15800.00,NULL,NULL,'Pending SSC',26,'Endorsed by Adviser Prof. Anna Reyes. Forwarded to SSC queue.',NULL,NULL,NULL,'2026-10-18 05:15:27','2026-10-18 05:15:27',NULL),(39,21,'Mathematics Olympiad & Gamified Instructional Kits Exhibit','Manipulative geometry sets, scientific calculators for quiz bee, and exhibit boards.','[{\"item\":\"Manipulative Algebra & Geometry Teaching Kits\",\"description\":\"3D geometric solids, fraction tiles, and probability sets\",\"qty\":12,\"unit_cost\":650,\"total\":7800},{\"item\":\"Math Olympiad Medals & Cash Prize Pool\",\"description\":\"Gold, Silver, Bronze medals and quiz bee materials\